<script setup>
import { computed } from 'vue';
import { formatMoney } from '@/Utils/format';
const props = defineProps({ trip: Object, stats: Object, projection: Object });
const emit = defineEmits(['close','tab']);
const blocks = computed(() => [!props.trip.products.length ? 'Agrega al menos un producto.' : null, Number(props.stats.gastos_sin_asignar_clp) !== 0 ? 'Distribuye todos los gastos.' : null, !Number(props.trip.tipo_cambio) ? 'Registra una tasa positiva.' : null].filter(Boolean));
</script>
<template>
    <section class="f-panel"><div class="f-panel-heading"><h2>Revisión antes del cierre</h2><span class="f-status" :class="{ 'f-status-warning': blocks.length }">{{ blocks.length ? `${blocks.length} bloqueos` : 'Costo conciliado' }}</span></div><div class="f-panel-body"><div class="f-breakdown-row"><span>Productos registrados</span><strong>{{ trip.products.length }} líneas · {{ projection.units }} unidades</strong></div><div class="f-breakdown-row"><span>Compra convertida</span><strong>${{ formatMoney(stats.total_productos_clp) }}</strong></div><div class="f-breakdown-row"><span>Gastos registrados</span><strong>${{ formatMoney(stats.total_gastos_clp) }}</strong></div><div class="f-breakdown-row"><span>Sin distribuir</span><strong :class="{ 'f-negative': Number(stats.gastos_sin_asignar_clp) !== 0 }">${{ formatMoney(stats.gastos_sin_asignar_clp) }}</strong></div><div class="f-breakdown-row"><span>Tasa de referencia</span><strong>{{ trip.tipo_cambio }} CLP / {{ trip.moneda_trabajo }}</strong></div><div class="f-breakdown-row"><span>Costo a conservar</span><strong>${{ formatMoney(stats.costo_total) }}</strong></div><div v-if="blocks.length" class="f-notice f-notice-error" style="margin-top:18px"><p v-for="block in blocks" :key="block">{{ block }}</p></div><div v-if="!projection.complete || trip.expenses.some(e => !trip.documents?.some(d => d.id === e.document_id))" class="f-notice" style="margin-top:18px"><strong>Advertencias que permiten cerrar</strong><p v-if="!projection.complete">Hay precios pendientes. El costo está disponible, pero la proyección del lote sigue incompleta.</p><p v-if="trip.expenses.some(e => !trip.documents?.some(d => d.id === e.document_id))">Hay gastos sin comprobante adjunto.</p></div><p class="f-hint" style="margin-top:18px">Al cerrar se conserva una revisión inmutable con tasas, entradas y reparto. Reabrir permite continuar trabajando sin modificar esa revisión.</p><div v-if="trip.estado === 'activo'" class="f-actions" style="margin-top:20px"><button class="f-button" @click="emit('tab','productos')">Revisar hoja</button><button class="f-button f-button-primary" :disabled="blocks.length > 0" @click="emit('close')">Cerrar importación</button></div><p v-else class="f-hint" style="margin-top:18px">La importación está cerrada. Consulta sus revisiones y reportes en Historial.</p></div></section>
</template>
